// LinkedIn enrichment strategies:
//
// Option A: Proxycurl API (paid, reliable)
//   POST https://nubela.co/proxycurl/api/linkedin/profile/resolve
//   { "first_name": "...", "last_name": "...", "company_name": "..." }
//
// Option B: Phantombuster (paid, automation)
//   Uses a phantom to search LinkedIn and return profile URLs
//
// Option C: Google Search API (free-ish)
//   site:linkedin.com/in "First Last" "Company"
//
// Option D: RocketReach / Apollo.io API (paid)
//
// We'll use Google Custom Search as the free default,
// with Proxycurl as the premium option.

const lead = $input.first().json;
const provider = 'CONFIGURE_LINKEDIN_PROVIDER'; // google, proxycurl, phantombuster

let searchUrl, searchBody, searchHeaders;

if (provider === 'proxycurl') {
  searchUrl = 'https://nubela.co/proxycurl/api/linkedin/profile/resolve';
  searchBody = null;
  searchHeaders = {
    'Authorization': 'Bearer CONFIGURE_PROXYCURL_API_KEY'
  };
  // Will be GET with params
} else {
  // Google Custom Search
  const query = `site:linkedin.com/in "${lead.first_name} ${lead.last_name}" "${lead.company_name || ''}"`;
  searchUrl = `https://www.googleapis.com/customsearch/v1?key=CONFIGURE_GOOGLE_API_KEY&cx=CONFIGURE_GOOGLE_CX&q=${encodeURIComponent(query)}&num=3`;
  searchHeaders = {};
}

return [{
  json: {
    lead_id: lead.id,
    lead_name: `${lead.first_name} ${lead.last_name}`,
    lead_company: lead.company_name,
    lead_email: lead.email,
    provider,
    searchUrl,
    searchHeaders,
    proxycurl_params: provider === 'proxycurl' ? {
      first_name: lead.first_name,
      last_name: lead.last_name,
      company_name: lead.company_name || undefined,
      similarity_checks: 'include',
      enrich_profile: 'skip'
    } : null
  }
}];

// Extract LinkedIn URL from search results
const response = $input.first().json;
const leadData = $('Build LinkedIn Search').first().json;

let linkedinUrl = null;
let profileData = {};

if (leadData.provider === 'proxycurl') {
  // Proxycurl returns direct profile URL
  linkedinUrl = response.body?.url || response.url || null;
  profileData = {
    headline: response.body?.headline || null,
    summary: response.body?.summary || null,
    location: response.body?.city || null,
    connections: response.body?.connections || null
  };
} else {
  // Google Custom Search results
  const items = response.body?.items || [];
  for (const item of items) {
    const url = item.link || '';
    if (url.includes('linkedin.com/in/')) {
      // Verify it's likely the right person
      const title = (item.title || '').toLowerCase();
      const leadName = leadData.lead_name.toLowerCase();
      const nameParts = leadName.split(' ');

      if (nameParts.some(part => title.includes(part))) {
        linkedinUrl = url;
        profileData = {
          title: item.title,
          snippet: item.snippet
        };
        break;
      }
    }
  }
}

return [{
  json: {
    lead_id: leadData.lead_id,
    linkedin_url: linkedinUrl,
    profile_data: profileData,
    found: !!linkedinUrl
  }
}];

// Add delay between requests to avoid rate limiting
// LinkedIn/Google are aggressive with rate limits
await new Promise(resolve => setTimeout(resolve, 3000 + Math.random() * 2000));
return $input.all();
